-- Wipe and reseed clauses for the car rental template.
DELETE FROM public.template_clauses
WHERE template_slug = 'dogovor-za-naem-na-avtomobil' AND locale = 'bg';

INSERT INTO public.template_clauses
  (template_slug, clause_id, title, body_md, include_when, "order", severity, locale, active)
VALUES
  ('dogovor-za-naem-na-avtomobil', 'subject', 'Предмет на договора',
   E'1.1. Наемодателят предоставя на Наемателя за временно възмездно ползване лек автомобил марка/модел **{{make_model}}**, с регистрационен номер **{{plate}}**, идентификационен номер на рамата (VIN) **{{vin}}** (наричан по-долу „Автомобила“).\n\n1.2. Автомобилът се предава в техническа изправност, заедно с свидетелство за регистрация (част II), валидна застраховка „Гражданска отговорност“, знак за технически преглед и комплект ключове, удостоверено с приемо-предавателен протокол.',
   NULL, 10, 'required', 'bg', true),

  ('dogovor-za-naem-na-avtomobil', 'term', 'Срок на наема',
   E'2.1. Срокът на наема е от **{{start_date}}** до **{{end_date}}**.\n\n2.2. Дневната наемна цена е **{{daily_rate}} EUR** с включен ДДС. Общата наемна цена се изчислява като произведение от дневната цена и броя на дните на ползване.\n\n2.3. Наемателят дължи заплащане на цялата сума при подписване на настоящия договор, освен ако страните не са уговорили друго в писмена форма.',
   NULL, 20, 'required', 'bg', true),

  ('dogovor-za-naem-na-avtomobil', 'deposit', 'Депозит',
   E'3.1. Наемателят внася при подписване на договора депозит в размер на **{{deposit}} EUR**, който служи за обезпечаване на задълженията му по договора.\n\n3.2. Депозитът се връща в пълен размер в срок до 7 (седем) работни дни след връщане на Автомобила без констатирани щети, неплатени глоби или нарушения.\n\n3.3. Наемодателят има право да удържи от депозита суми за покриване на щети, глоби, такси или неустойки, дължими от Наемателя.',
   'deposit', 25, 'recommended', 'bg', true),

  ('dogovor-za-naem-na-avtomobil', 'km', 'Лимит на пробега',
   E'4.1. Дневният лимит на пробега е **{{km_limit}} км**. При надвишаване Наемателят дължи допълнителна такса от 0,15 EUR за всеки превишен километър, освен ако в писмено приложение не е уговорена друга ставка.\n\n4.2. Действителният пробег се установява по показанията на одометъра при приемо-предавателните протоколи.',
   'km_limit', 30, 'recommended', 'bg', true),

  ('dogovor-za-naem-na-avtomobil', 'fuel', 'Гориво',
   E'5.1. Политика за гориво: **{{fuel_policy}}**.\n\n5.2. Разходите за гориво по време на наема са изцяло за сметка на Наемателя. Наемателят е длъжен да зарежда само гориво от типа, посочен в свидетелството за регистрация на Автомобила. При зареждане на неподходящо гориво всички разходи за отстраняване на щетите са за сметка на Наемателя.',
   NULL, 35, 'required', 'bg', true),

  ('dogovor-za-naem-na-avtomobil', 'insurance', 'Застраховка „Каско“',
   E'6.1. За срока на наема Наемодателят за своя сметка осигурява валидна застраховка „Каско“ на Автомобила, която покрива щети при пътно-транспортно произшествие, кражба, пожар и природни бедствия.\n\n6.2. Самоучастието по застраховката се поема от Наемателя в случай на установена негова вина.\n\n6.3. Застраховката не покрива щети, причинени умишлено, при шофиране в нетрезво състояние, под въздействието на наркотични вещества, без валидно свидетелство за управление или при участие в спортни прояви.',
   'insurance_included == true', 40, 'recommended', 'bg', true),

  ('dogovor-za-naem-na-avtomobil', 'lessee_obligations', 'Задължения на Наемателя',
   E'7.1. Наемателят се задължава:\n  а) да управлява Автомобила лично или да го предоставя само на лица, изрично посочени в писмено приложение;\n  б) да спазва всички правила за движение по пътищата;\n  в) да не превозва с Автомобила опасни товари, повече пътници от допустимия брой и да не го използва за такси, обучение или състезателни цели;\n  г) да не извършва ремонти или модификации без писмено съгласие на Наемодателя;\n  д) незабавно да уведоми Наемодателя и компетентните органи при настъпило ПТП, повреда или кражба.',
   NULL, 50, 'required', 'bg', true),

  ('dogovor-za-naem-na-avtomobil', 'abroad_forbidden', 'Извеждане извън страната',
   E'8.1. Извеждането на Автомобила извън територията на Република България е **забранено** без предварително писмено съгласие на Наемодателя. При нарушение Наемателят дължи неустойка в размер на 30% от общата наемна цена и носи пълна имуществена отговорност за всички възникнали щети.',
   'abroad_allowed == false', 55, 'recommended', 'bg', true),

  ('dogovor-za-naem-na-avtomobil', 'return', 'Връщане на Автомобила',
   E'9.1. Автомобилът се връща на адреса на Наемодателя на крайната дата на наема в часа на първоначалното предаване, в същото техническо състояние, в което е приет, отчитайки нормалното износване.\n\n9.2. Връщането се удостоверява с подписан приемо-предавателен протокол, в който се описват установените щети, пробегът и нивото на горивото.\n\n9.3. При закъсняло връщане Наемателят дължи допълнителна дневна такса в размер на 150% от уговорената дневна цена за всеки започнат ден на забавата.',
   NULL, 60, 'required', 'bg', true),

  ('dogovor-za-naem-na-avtomobil', 'termination', 'Прекратяване',
   E'10.1. Договорът се прекратява с изтичане на уговорения срок, по взаимно съгласие на страните в писмена форма или едностранно от изправната страна при съществено неизпълнение.\n\n10.2. При предсрочно прекратяване по вина на Наемателя, заплатената наемна цена не се възстановява.',
   NULL, 70, 'recommended', 'bg', true),

  ('dogovor-za-naem-na-avtomobil', 'governing_law', 'Приложимо право и спорове',
   E'11.1. За неуредените въпроси се прилагат разпоредбите на Закона за задълженията и договорите и действащото българско законодателство.\n\n11.2. Възникналите спорове страните разрешават чрез преговори, а при непостигане на съгласие — пред компетентния български съд.',
   NULL, 80, 'optional', 'bg', true);
